<?php use App\Core\Csrf; $editing=!empty($invoice['id']); ?>
<?php if($errors): ?><div class="alert error"><?= implode('<br>',array_map(static fn($e)=>htmlspecialchars((string)$e),$errors)) ?></div><?php endif; ?>
<form class="record-form invoice-form" action="<?= $editing?'/invoices/'.(int)$invoice['id']:'/invoices' ?>" method="post"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token()) ?>">
<section class="form-card"><div class="form-heading"><span>01</span><div><h2>Invoice details</h2><p>Choose the customer, dates and initial invoice status.</p></div></div><div class="form-grid"><label>Customer *<select id="invoice-customer" name="customer_id" required><option value="">Select customer</option><?php foreach($customers as $customer): ?><option value="<?= (int)$customer['id'] ?>" <?= (int)($invoice['customer_id']??0)===(int)$customer['id']?'selected':'' ?>><?= htmlspecialchars((string)($customer['company_name']?:$customer['contact_name'])) ?> · <?= htmlspecialchars((string)$customer['account_number']) ?></option><?php endforeach; ?></select></label><label>Related order<select id="invoice-order" name="order_id"><option value="">No related order</option><?php foreach($orders as $order): ?><option value="<?= (int)$order['id'] ?>" data-customer="<?= (int)$order['customer_id'] ?>" <?= (int)($invoice['order_id']??0)===(int)$order['id']?'selected':'' ?>><?= htmlspecialchars((string)$order['order_number']) ?> · <?= htmlspecialchars((string)$order['description']) ?></option><?php endforeach; ?></select></label><label>Issue date<input type="date" name="issue_date" value="<?= htmlspecialchars((string)($invoice['issue_date']??'')) ?>" required></label><label>Due date<input type="date" name="due_date" value="<?= htmlspecialchars((string)($invoice['due_date']??'')) ?>" required></label><label>Status<select name="status"><option value="draft" <?= ($invoice['status']??'')==='draft'?'selected':'' ?>>Draft</option><option value="sent" <?= ($invoice['status']??'')==='sent'?'selected':'' ?>>Sent / outstanding</option></select></label></div></section>
<section class="form-card"><div class="form-heading"><span>02</span><div><h2>Invoice items</h2><p>Add each product, service or fee. Totals are calculated when saved.</p></div></div><div class="invoice-items" id="invoice-items"><?php foreach($items as $item): ?><div class="invoice-item"><input name="item_description[]" value="<?= htmlspecialchars((string)($item['description']??'')) ?>" placeholder="Description"><input inputmode="decimal" name="item_quantity[]" value="<?= htmlspecialchars((string)($item['quantity']??'1')) ?>" placeholder="Qty"><input inputmode="decimal" name="item_price[]" value="<?= htmlspecialchars((string)($item['unit_price']??'')) ?>" placeholder="Unit price (£)"><button type="button" class="remove-line">×</button></div><?php endforeach; ?></div><button id="add-line" class="text-button" type="button">+ Add invoice item</button></section>
<section class="form-card"><div class="form-heading"><span>03</span><div><h2>Customer notes</h2><p>Optional payment terms or information shown on the invoice.</p></div></div><label>Notes<textarea name="notes" rows="5" placeholder="Thank you for your business."><?= htmlspecialchars((string)($invoice['notes']??'')) ?></textarea></label></section><div class="form-actions"><a class="secondary-button" href="<?= $editing?'/invoices/'.(int)$invoice['id']:'/invoices' ?>">Cancel</a><button class="primary-button" type="submit"><?= $editing?'Save changes':'Create invoice' ?></button></div></form>
<template id="invoice-line"><div class="invoice-item"><input name="item_description[]" placeholder="Description"><input inputmode="decimal" name="item_quantity[]" value="1" placeholder="Qty"><input inputmode="decimal" name="item_price[]" placeholder="Unit price (£)"><button type="button" class="remove-line">×</button></div></template><script>const lines=document.getElementById('invoice-items');document.getElementById('add-line').addEventListener('click',()=>lines.append(document.getElementById('invoice-line').content.cloneNode(true)));lines.addEventListener('click',e=>{if(e.target.classList.contains('remove-line')&&lines.children.length>1)e.target.closest('.invoice-item').remove()});document.getElementById('invoice-order').addEventListener('change',e=>{const c=e.target.selectedOptions[0]?.dataset.customer;if(c)document.getElementById('invoice-customer').value=c});</script>
